export const OLD5_PRECOMPUTED_RESULTS = Object.freeze({ old5_frost_dragon: FROST, old5_kujeska: KUJESKA });
function normalizeLegacyCutoffLabel(label = '') {
  return String(label)
    .replace(/の行動機会直後/g, 'の行動後')
    .replace(/最後の味方行動直後/g, '最後の味方行動後')
    .replace(/最後の味方行動後（従来）/g, '最後の味方行動後');
}
export function reviveOld5PrecomputedResult(raw) {
  if (!raw) return null;
  return {
    ...raw,
    precomputedExact: true,
    finalTurnCutoffLabel: normalizeLegacyCutoffLabel(raw.finalTurnCutoffLabel),
    hpDistribution: new Map(raw.hpDistribution),
    timeline: raw.timeline.map(x => ({ ...x, label: normalizeLegacyCutoffLabel(x.label) })),
    finalOrder: raw.finalOrder.map(x => ({ ...x })),
    missingCommandProfiles: raw.missingCommandProfiles.slice(),
    missingCommandEffects: raw.missingCommandEffects.slice(),
    activeCompanionCommandProfiles: raw.activeCompanionCommandProfiles.slice(),
    missingCompanionCommandProfiles: raw.missingCompanionCommandProfiles.slice(),
    inheritedCompanionCommandBaselines: raw.inheritedCompanionCommandBaselines.slice(),
    enemySkillActivation: raw.enemySkillActivation.map(x => ({ ...x })),
    allySkillActivation: raw.allySkillActivation.map(row => row.map(x => ({ ...x }))),
    statusSummaryByTurn: raw.statusSummaryByTurn.map(row => row.map(x => ({ ...x }))),
    scenarioCountByTurn: raw.scenarioCountByTurn.slice(),
    enemyExFailureByTurn: raw.enemyExFailureByTurn.slice(),
    playerExGaugeDistribution: new Map(raw.playerExGaugeDistribution),
    enemyExGaugeDistribution: new Map(raw.enemyExGaugeDistribution)
  };
}
